CREATE TEMP TABLE lesson_tenants (
  tenant_id INTEGER PRIMARY KEY,
  tenant_code TEXT NOT NULL UNIQUE
);
INSERT INTO pg_temp.lesson_tenants
SELECT tenant_id, 'T' || LPAD(tenant_id::TEXT, 3, '0')
FROM generate_series(1, 100) AS g(tenant_id);
CREATE TEMP TABLE lesson_tenant_events (
  event_id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES pg_temp.lesson_tenants(tenant_id),
  event_day DATE NOT NULL,
  payload_bucket TEXT NOT NULL
);
INSERT INTO pg_temp.lesson_tenant_events (event_id, tenant_id, event_day, payload_bucket)
SELECT row_no,
       CASE WHEN row_no <= 90 THEN 1 ELSE 2 + ((row_no - 91) % 10) END,
       DATE '2026-10-01' + ((row_no - 1) % 7),
       CASE WHEN row_no % 2 = 0 THEN 'even' ELSE 'odd' END
FROM generate_series(1, 100) AS g(row_no);

